ers carry out their own work.","These program resources support analysis and planning. They do not replace official policy, required consultation, or the authority of the responsible office."],"nextActions":[{"label":"Read the guide","href":"/library/one-dsd-planning/One_DSD_Quarterly_Report_Dashboard_Guide.html"},{"label":"Download Word document","href":"/library/one-dsd-planning/One_DSD_Quarterly_Report_Dashboard_Guide.docx"}],"tags":["equity analysis","policy","review","planning","reporting","progress","measures"],"intents":["practice_method","policy_orientation","next_actions"],"owner":"One DSD People, Access and Culture","reviewDate":"2026-10-05","status":"approved","scope":"agencywide","accessibility":"pending","version":"2026-10-05","provenance":"Adapted from the owner-supplied complete source package. Original files retained separately."},{"id":"guide-one-dsd-measures","title":"Data and measures","summary":"Use the 21-measure framework to define evidence, its source, its limits, and who can act on it.","type":"external_reference","authority":"guidance","layer":"L3","body":["Use the 21-measure framework to define evidence, its source, its limits, and who can act on it.","Staff throughout DHS can use these resources independently. The Equity and Inclusion Operations Consultant leads the program and offers guidance and feedback; staff and decision owners carry out their own work.","These program resources support analysis and planning. They do not replace official policy, required consultation, or the authority of the responsible office."],"nextActions":[{"label":"Read the guide","href":"/library/one-dsd-planning/One_DSD_Data_and_Metrics_Framework.html"},{"label":"Download Word document","href":"/library/one-dsd-planning/One_DSD_Data_and_Metrics_Framework.docx"}],"tags":["equity analysis","policy","review","planning","reporting","progress","measures"],"intents":["practice_method","policy_orientation","next_actions"],"owner":"One DSD People, Access and Culture","reviewDate":"2026-10-05","status":"approved","scope":"agencywide","accessibility":"pending","version":"2026-10-05","provenance":"Adapted from the owner-supplied complete source package. Original files retained separately."},{"id":"guide-one-dsd-work-plan","title":"Equity implementation work plan","summary":"Connect priorities to practical actions, responsible owners, evidence, and review points.","type":"external_reference","authority":"guidance","layer":"L3","body":["Connect priorities to practical actions, responsible owners, evidence, and review points.","Staff throughout DHS can use these resources independently. The Equity and Inclusion Operations Consultant leads the program and offers guidance and feedback; staff and decision owners carry out their own work.","These program resources support analysis and planning. They do not replace official policy, required consultation, or the authority of the responsible office."],"nextActions":[{"label":"Read the guide","href":"/library/one-dsd-planning/DSD_Equity_Implementation_Work_Plan.html"},{"label":"Download Word document","href":"/library/one-dsd-planning/DSD_Equity_Implementation_Work_Plan.docx"}],"tags":["equity analysis","policy","review","planning"],"intents":["practice_method","policy_orientation","next_actions"],"owner":"One DSD People, Access and Culture","reviewDate":"2026-10-05","status":"approved","scope":"agencywide","accessibility":"pending","version":"2026-10-05","provenance":"Adapted from the owner-supplied complete source package. Original files retained separately."},{"id":"tool-one-dsd-structural-review","title":"Structural equity analysis","summary":"Trace barriers through a process, examine decision rights and evidence, and plan a change with a responsible role and a review date.","type":"tool","authority":"guidance","layer":"L2","body":["Examine a policy, service, or workplace process anywhere in DHS. Start with the pattern, map decision points, question requirements, identify decision rights, and consider how different experiences combine.","Review the process history and evidence, including missing information. Plan a change with a responsible role, a review date, a measure, and a way to report back to affected people.","Work independently or with colleagues. The Equity and Inclusion Operations Consultant leads the program and offers guidance and feedback. The role responsible for a process carries its decisions and follow-through.","This interactive workspace provides optional saving on your device, downloadable reports, and a working copy you can reopen. Keep personal and confidential records out of the review. A completed record does not verify an equitable result."],"nextActions":[{"label":"Open structural equity analysis","href":"/equity-review/structural"},{"label":"Explore related equity tools","href":"/equity-review"}],"tags":["structural equity","equity analysis","policy","process","barriers","decision rights","intersectionality","evidence","follow-through"],"intents":["practice_method","policy_orientation","next_actions","access_barriers"],"owner":"One DSD People, Access and Culture","reviewDate":"2026-10-05","status":"approved","scope":"agencywide","accessibility":"pending","version":"2026-10-05","provenance":"Adapted from the owner's supplied DSD Structural Analysis Tool HTML. The original is retained in the integration evidence."}]$dsd_current_resources$::jsonb) loop
scope:=case when item->>'scope'='dsd' then 'dsd' else 'one-dhs' end; sid:='standalone-current:'||(item->>'id');
insert into pac_dsd.source_items(source_item_id,source_business_id,carrier_id,source_pointer,title,normalized_payload,normalized_item_sha256,hash_algorithm,hash_algorithm_version,owner_approval_status,accounting_status,access_scope,sensitivity_class,deidentification_status,ordinary_indexing_allowed,model_context_allowed) values(sid,item->>'id',carrier,item->>'id',item->>'title',item,encode(pac_dsd.digest(item::text,'sha256'),'hex'),'sha256','1','owner_approved_for_ingestion','accounted','staff_candidate','S0','not_needed',true,false);
insert into pac_dsd.content_items(content_item_id,content_kind,default_scope_id,staff_label,created_by,sensitivity_class) values(item->>'id','resource',scope,item->>'title','explicit_owner_standalone_direction','S0');
insert into pac_dsd.content_revisions(content_item_id,revision_number,canonical_payload,change_summary,required_review_dimensions,created_by,sensitivity_class,ordinary_indexing_allowed,model_context_allowed,limitations) values(item->>'id',1,item,'Exact current public static definition initialized for separate One DSD editing.','{}','explicit_owner_standalone_direction','S0',true,false,array['Exact current source copy; no new independent factual or accessibility review claimed.']) returning revision_id into version;
insert into pac_dsd.revision_sources(revision_id,source_item_id,relationship,note) values(version,sid,'primary','Exact current static resource; no private or operational records copied.');
perform pac_dsd.assert_resource_staff_release(version);
insert into pac_dsd.publication_decisions(content_item_id,revision_id,scope_id,decision,gate_snapshot,decided_by,reason,sensitivity_class,unauthenticated_exposure_permitted,exposure_reason) values(item->>'id',version,scope,'publish',jsonb_build_object('approvalBasis','explicit_owner_standalone_direction','explicitOwnerDecision',true,'exactCurrentSourcePreserved',true,'automaticValidationCompleted',true,'independentFactualReviewPerformed',false,'independentAccessibilityAuditPerformed',false,'staff_release_explicit',true),'explicit_owner_standalone_direction','Initialize existing approved public resources for the separate division application.','S0',true,'Already public source resources; current exact source copied under explicit standalone application direction.');
end loop;
end $seed$;
commit;
